CREATE OR REPLACE FUNCTION public.native_task_travel_pace_v1(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  u uuid := auth.uid(); p public.user_profiles%rowtype; trip uuid;
  pace text; source text := 'none'; rev bigint; operation uuid;
begin
  perform identity_private.mobile_session_v2('session');
  if p_input is null or jsonb_typeof(p_input) <> 'object'
    or (p_input - array['tripId','currentPace','useSaved','expectedSourceRevision']) <> '{}'::jsonb
    or jsonb_typeof(p_input->'tripId') is distinct from 'string'
    or (p_input->>'tripId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or jsonb_typeof(p_input->'useSaved') is distinct from 'boolean'
    or not (p_input ? 'currentPace')
    or (p_input->'currentPace' <> 'null'::jsonb and p_input->>'currentPace' not in ('relaxed','balanced','packed'))
    or (p_input ? 'expectedSourceRevision' and (jsonb_typeof(p_input->'expectedSourceRevision') is distinct from 'number'
      or (p_input->>'expectedSourceRevision') !~ '^(0|[1-9][0-9]{0,15})$'))
    then raise exception 'INVALID_INPUT'; end if;
  trip := (p_input->>'tripId')::uuid;
  if not exists(select 1 from public.trips where id=trip and owner_id=u) then raise exception 'FORBIDDEN'; end if;
  select * into p from public.user_profiles where owner_id=u;
  if p_input->>'currentPace' is not null then
    pace := p_input->>'currentPace'; source := 'current_input';
  elsif (p_input->>'useSaved')::boolean and p.pace_state='explicit'
    and p.pace_notice='local-planning-cross-trip-v1' then
    pace := p.travel_pace; source := 'profile'; rev := p.pace_revision; operation := p.pace_operation;
  end if;
  if p_input ? 'expectedSourceRevision' and (source <> 'profile'
    or rev is distinct from (p_input->>'expectedSourceRevision')::bigint) then raise exception 'PACE_STALE_SOURCE'; end if;
  return jsonb_build_object('schemaVersion','task-travel-pace/1','tripId',trip,
    'travelPace',pace,'source',source,'sourceRevision',rev,'sourceOperationId',operation,
    'purpose','local_trip_planning');
end $function$

CREATE OR REPLACE FUNCTION public.native_travel_pace_v1(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  u uuid := auth.uid();
  p public.user_profiles%rowtype;
  op uuid; expected bigint; action text := p_input->>'action';
  before_value jsonb;
begin
  -- Locks the mobile epoch before the Profile row, including read/replay paths.
  perform identity_private.mobile_session_v2('session');
  if p_input is null or jsonb_typeof(p_input) <> 'object' then raise exception 'INVALID_INPUT'; end if;
  if action = 'read' then
    if p_input <> '{"action":"read"}'::jsonb then raise exception 'INVALID_INPUT'; end if;
    select * into p from public.user_profiles where owner_id=u;
    return memory_private.pace_json(p);
  end if;
  if action is null or action not in ('save','pause','revoke','undo')
    or (p_input - array['action','operationId','expectedRevision','travelPace','noticeVersion']) <> '{}'::jsonb
    or jsonb_typeof(p_input->'operationId') is distinct from 'string'
    or (p_input->>'operationId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or jsonb_typeof(p_input->'expectedRevision') is distinct from 'number'
    or (p_input->>'expectedRevision') !~ '^(0|[1-9][0-9]{0,15})$'
    then raise exception 'INVALID_INPUT'; end if;
  expected := (p_input->>'expectedRevision')::bigint;
  if expected > 9007199254740990 then raise exception 'INVALID_INPUT'; end if;
  if action='save' then
    if (p_input->>'travelPace') is null or p_input->>'travelPace' not in ('relaxed','balanced','packed')
      or p_input->>'noticeVersion' is distinct from 'local-planning-cross-trip-v1'
      then raise exception 'INVALID_INPUT'; end if;
  elsif p_input ? 'travelPace' or p_input ? 'noticeVersion' then raise exception 'INVALID_INPUT'; end if;
  op := (p_input->>'operationId')::uuid;
  insert into public.user_profiles(owner_id) values(u) on conflict on constraint user_profiles_pkey do nothing;
  select * into p from public.user_profiles where owner_id=u for update;
  if p.pace_operation=op then
    if p.pace_request is distinct from p_input then raise exception 'PACE_OPERATION_REUSE'; end if;
    return memory_private.pace_json(p) || '{"reused":true}'::jsonb;
  end if;
  -- An older operation after correction/revocation is rejected, never replayed.
  if expected <> p.pace_revision then raise exception 'PACE_CONFLICT'; end if;
  if action='pause' and p.pace_state <> 'explicit' then raise exception 'PACE_CONFLICT'; end if;
  if action='undo' and (p.pace_request->>'action' is distinct from 'save' or p.pace_undo is null)
    then raise exception 'PACE_CONFLICT'; end if;
  before_value := case when action='save' then jsonb_build_object(
    'travelPace',p.travel_pace,'state',p.pace_state,'noticeVersion',p.pace_notice) else null end;
  update public.user_profiles set
    travel_pace = case action when 'save' then p_input->>'travelPace'
      when 'revoke' then 'balanced' when 'undo' then p.pace_undo->>'travelPace' else p.travel_pace end,
    pace_state = case action when 'save' then 'explicit' when 'pause' then 'paused'
      when 'revoke' then 'revoked' else p.pace_undo->>'state' end,
    pace_notice = case action when 'save' then p_input->>'noticeVersion' when 'revoke' then null
      when 'undo' then p.pace_undo->>'noticeVersion' else p.pace_notice end,
    pace_revision = p.pace_revision + 1, pace_operation=op, pace_request=p_input,
    pace_undo=before_value, updated_at=clock_timestamp()
    where owner_id=u returning * into p;
  return memory_private.pace_json(p) || '{"reused":false}'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.read_local_recovery_operation_v1(p_trip_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$declare u uuid;t public.trips%rowtype;o recovery_private.operations_v1%rowtype;p public.trip_proposals%rowtype;c recovery_private.contexts_v1%rowtype;b recovery_private.lineage_v1%rowtype;state text;version integer;profile jsonb;orders jsonb;begin
 if p_trip_id is null or p_operation_id is null then raise exception 'INVALID_INPUT';end if;
 u:=recovery_private.actor_v1();t:=recovery_private.trip_v1(u,p_trip_id);if t.id is null then return jsonb_build_object('kind','unavailable');end if;
 select * into o from recovery_private.operations_v1 where owner_id=u and trip_id=t.id and operation_id=p_operation_id;if not found then return jsonb_build_object('kind','unavailable');end if;
 -- Read only the original exact Proposal named by this immutable operation ACK.
 select e.resulting_version into version from public.trip_events e join recovery_private.lineage_v1 l on l.proposal_id=e.proposal_id where l.owner_id=u and l.operation_id=o.operation_id and e.proposal_id=o.proposal_id and e.owner_id=u and e.trip_id=t.id and e.event_type='proposal_applied' order by e.resulting_version limit 1;
 if found then state:='applied';else
 select * into p from public.trip_proposals where id=o.proposal_id;
 select * into c from recovery_private.contexts_v1 where id=o.context_id;
 state:=case when p.status='rejected' then 'rejected' when p.expires_at<=clock_timestamp() or c.expires_at<=clock_timestamp() or p.status='expired' then 'expired' when p.status<>'pending' or t.head_version<>p.base_trip_version then 'stale' else 'pending' end;
 if state='pending' and c.traffic_basis is not null and recovery_private.transport_basis_v1((c.traffic_basis->>'receiptId')::uuid,c.traffic_basis->'scope') is distinct from c.traffic_basis then state:='stale';end if;
 if state='pending' then profile:=recovery_private.profile_v1(u);orders:=recovery_private.reservations_v1(u,t.id,t.head_version);if profile<>c.profile_basis or orders->>'kind' is distinct from 'basis' or orders->'items' is distinct from c.reservation_basis then state:='stale';end if;end if;
 end if;
 return jsonb_build_object('kind','local_recovery_operation/1','operationId',o.operation_id,'tripId',o.trip_id,'input',o.input,'receipt',o.receipt||'{"reused":true}','state',state,'resultingVersion',version);
exception when lock_not_available then return jsonb_build_object('kind','unavailable');end $function$

CREATE OR REPLACE FUNCTION public.read_scoped_trip_edit_work_v1(p_turn_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare j scoped_edit_private.work_v1%rowtype;c scoped_edit_private.contexts_v1%rowtype;cfg scoped_edit_private.worker_settings_v1%rowtype;tp turn_private.text_policies%rowtype;profile jsonb;mem jsonb;begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN';end if;
 select * into j from scoped_edit_private.work_v1 where turn_id=p_turn_id;
 if j.binding->>'leaseToken' is distinct from p_lease_token::text or not scoped_edit_private.work_current_v1(j.binding) then return jsonb_build_object('kind','pending');end if;
 select * into c from scoped_edit_private.contexts_v1 where id=j.context_id;select * into cfg from scoped_edit_private.worker_settings_v1 where policy_id=j.policy_id;select * into tp from turn_private.text_policies where id=j.policy_id;
 select jsonb_build_object('travelPace',travel_pace,'revision',pace_revision) into profile from public.user_profiles where owner_id=j.owner_id and pace_state='explicit' and pace_notice='local-planning-cross-trip-v1' and cfg.allow_profile;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'revision',p.revision,'summary',p.summary,'constraintKind',p.constraint_kind) order by p.id),'[]') into mem from public.memory_profiles p join public.memory_consents mc on mc.id=p.consent_id and mc.owner_id=p.owner_id and mc.status='granted' where p.owner_id=j.owner_id and p.state in('explicit','confirmed') and p.summary is not null and cfg.allow_memory;
 if jsonb_array_length(mem)>64 then return jsonb_build_object('kind','pending');end if;
 return jsonb_build_object('kind','scoped_edit_input/1','binding',j.binding,'context',scoped_edit_private.context_wire_v1(c),'text',(select input_text from turn_private.text_content where turn_id=j.turn_id),'locale',c.input->'locale','profile',profile,'memory',mem,'endpoint',tp.endpoint,'reservedMicros',cfg.reserved_micros,'timeoutMs',cfg.timeout_ms,'maxOutputTokens',cfg.max_output_tokens);
end $function$

CREATE OR REPLACE FUNCTION recovery_private.confirm_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$declare p public.trip_proposals%rowtype;b recovery_private.lineage_v1%rowtype;c recovery_private.contexts_v1%rowtype;t public.trips%rowtype;profile jsonb;orders jsonb;dig text;o recovery_private.operations_v1%rowtype;proof recovery_private.transport_proofs_v1%rowtype;begin
 select * into p from public.trip_proposals where id=NEW.proposal_id;
 if not p.local_recovery then return null;end if;
 select * into b from recovery_private.lineage_v1 where proposal_id=p.id;
 if not found then raise exception 'RECOVERY_CONFIRM_GUARD';end if;
 select * into c from recovery_private.contexts_v1 where id=b.context_id;
 select * into o from recovery_private.operations_v1 where owner_id=b.owner_id and operation_id=b.operation_id;
 t:=recovery_private.trip_v1(recovery_private.actor_v1(),p.trip_id);
 select digest into dig from public.read_trip_proposal_v2(p.id);
 if c.id is null or o.proposal_id is null or t.id is null or b.owner_id is distinct from auth.uid() or p.owner_id<>b.owner_id or NEW.owner_id<>b.owner_id or NEW.trip_id<>b.trip_id or p.trip_id<>b.trip_id or p.patch<>b.patch or dig is distinct from b.proposal_digest
 or p.base_trip_version<>c.base_version or NEW.resulting_version<>c.base_version+1 or t.head_version<>NEW.resulting_version or p.status<>'applied' or p.rollback_snapshot_version is not null
 or p.expires_at<=clock_timestamp() or c.expires_at<=clock_timestamp() or p.expires_at>c.expires_at or p.expires_at is distinct from (o.receipt->>'expiresAt')::timestamptz
 or b.patch<>recovery_private.patch_v1(c,o.input->>'candidateId') or public.trip_content_snapshot(t.id,t.title)<>public.apply_trip_content_patch(c.snapshot,b.patch) then raise exception 'RECOVERY_CONFIRM_GUARD';end if;
 if c.traffic_basis is not null then
 select * into proof from recovery_private.transport_proofs_v1 where transaction_id=pg_current_xact_id() and proposal_id=p.id;
 if not found or proof.root_proposal_id is distinct from o.proposal_id or proof.owner_id<>b.owner_id or proof.trip_id<>b.trip_id or proof.context_id<>c.id or proof.proposal_digest is distinct from dig or proof.proposal_revision<>p.revision or proof.base_version<>p.base_trip_version or proof.actor_basis is distinct from recovery_private.actor_basis_v1() or proof.traffic_basis is distinct from c.traffic_basis or proof.checked_at>clock_timestamp() or proof.expires_at<=clock_timestamp() or not recovery_private.transport_proof_current_v1(proof.traffic_basis) then raise exception 'RECOVERY_TRANSPORT_GUARD';end if;
 delete from recovery_private.transport_proofs_v1 where transaction_id=proof.transaction_id and proposal_id=proof.proposal_id;
 end if;
 profile:=recovery_private.profile_v1(b.owner_id);orders:=recovery_private.reservations_v1(b.owner_id,b.trip_id,NEW.resulting_version);
 if profile<>c.profile_basis or orders->>'kind' is distinct from 'basis' or orders->'items' is distinct from c.reservation_basis then raise exception 'RECOVERY_CONFIRM_GUARD';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION recovery_private.prepare_context_v1(p_trip_id uuid, p_input jsonb, p_traffic jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$declare u uuid;t public.trips%rowtype;c recovery_private.contexts_v1%rowtype;profile jsonb;orders jsonb;snap jsonb;observed timestamptz;b jsonb;record jsonb;item public.trip_items%rowtype;day public.trip_days%rowtype;zone text;start_date date;end_date date;begin
 if p_trip_id is null or (p_traffic is null and not recovery_private.valid_prepare_v1(p_input)) or (p_traffic is not null and not recovery_private.valid_transport_v1(p_input)) then raise exception 'INVALID_INPUT';end if;
 u:=recovery_private.actor_v1();t:=recovery_private.trip_v1(u,p_trip_id);if t.id is null then return jsonb_build_object('kind','unavailable');end if;
 select * into c from recovery_private.contexts_v1 where owner_id=u and operation_id=(p_input->>'operationId')::uuid for update nowait;
 if found and (c.trip_id<>t.id or c.input<>p_input) then return jsonb_build_object('kind','conflict');end if;
 if t.head_version<>(p_input->>'expectedHeadVersion')::integer then return jsonb_build_object('kind','conflict');end if;
 if p_traffic is null then
 observed:=recovery_private.time_v1(p_input->'report'->>'observedAt');if observed>clock_timestamp() or observed+interval '5 minutes'<=clock_timestamp() then return jsonb_build_object('kind','stale');end if;
 if p_input->'report'->>'kind'='high_risk_unwell' then return jsonb_build_object('kind','pending','reason','HIGH_RISK_UNWELL');end if;
 else
 if p_input->'scope'->>'tripId' is distinct from t.id::text or not exists(select 1 from public.trip_items where trip_id=t.id and owner_id=u and day_id=p_input->>'dayId' and item_id=p_input->'scope'->>'itemId') then return jsonb_build_object('kind','conflict');end if;
 end if;
 if c.id is not null and c.expires_at<=clock_timestamp() then return jsonb_build_object('kind','stale');end if;
 if exists(select 1 from jsonb_array_elements_text(p_input->'selectedItemIds')x where not exists(select 1 from public.trip_items i where i.trip_id=t.id and i.owner_id=u and i.day_id=p_input->>'dayId' and i.item_id=x))
 or exists(select 1 from jsonb_array_elements_text(p_input->'fixedItemIds')x where not exists(select 1 from public.trip_items i where i.trip_id=t.id and i.owner_id=u and i.item_id=x))
 or exists(select 1 from jsonb_array_elements(p_input->'selectedItemIds')x where p_input->'fixedItemIds' @> jsonb_build_array(x)) then return jsonb_build_object('kind','conflict');end if;
 profile:=recovery_private.profile_v1(u);orders:=recovery_private.reservations_v1(u,t.id,t.head_version);if orders->>'kind' is distinct from 'basis' then return orders;end if;
 if exists(select 1 from jsonb_array_elements(orders->'items')x where x->>'status'='unknown' or coalesce(x->>'status','') not in('reserved','amended','cancelled')) then return jsonb_build_object('kind','pending','reason','RESERVATION_STATUS_UNKNOWN');end if;
 if exists(select 1 from jsonb_array_elements(orders->'items')x where x->>'status' in('reserved','amended') and not exists(select 1 from jsonb_array_elements(p_input->'reservationBindings')binding_rows(value) where (binding_rows.value->>'referenceId')::uuid::text=x->>'referenceId' and binding_rows.value->'revision'=x->'revision')) then return jsonb_build_object('kind','pending','reason','RESERVATION_SCOPE_UNMAPPED');end if;
 -- A binding is user-confirmed preservation, never supplier or mapping proof.
 if (select count(distinct jsonb_build_array(x->>'dayId',x->>'itemId')) from jsonb_array_elements(p_input->'reservationBindings')x)<>jsonb_array_length(p_input->'reservationBindings') then return jsonb_build_object('kind','pending','reason','RESERVATION_BINDING_AMBIGUOUS');end if;
 for b in select value from jsonb_array_elements(p_input->'reservationBindings') loop
 select x into record from jsonb_array_elements(orders->'records')x where x->>'referenceId'=(b->>'referenceId')::uuid::text and x->'revision'=b->'revision';
 if not found then return jsonb_build_object('kind','pending','reason','RESERVATION_BINDING_STALE');end if;
 select * into item from public.trip_items i where i.trip_id=t.id and i.owner_id=u and i.day_id=b->>'dayId' and i.item_id=b->>'itemId';
 if not found then return jsonb_build_object('kind','pending','reason','RESERVATION_BINDING_STALE');end if;
 if p_input->'selectedItemIds' @> jsonb_build_array(item.item_id) then return jsonb_build_object('kind','pending','reason','RESERVATION_FIXED_SELECTION');end if;
 select * into day from public.trip_days d where d.trip_id=t.id and d.day_id=item.day_id;
 zone:=record->'fields'->>'timeZone';
 if record->'fields'->>'startsAt' is not null or record->'fields'->>'endsAt' is not null then
 if zone is null or not exists(select 1 from pg_timezone_names where name=zone) then return jsonb_build_object('kind','pending','reason','RESERVATION_DATE_UNRESOLVED');end if;
 start_date:=(recovery_private.time_v1(record->'fields'->>'startsAt') at time zone zone)::date;
 end_date:=(recovery_private.time_v1(record->'fields'->>'endsAt') at time zone zone)::date;
 if start_date is not null and day.trip_date<start_date or end_date is not null and day.trip_date>end_date
 or record->'fields'->>'kind'<>'lodging' and item.starts_at is not null and recovery_private.time_v1(record->'fields'->>'startsAt') is not null and item.starts_at<recovery_private.time_v1(record->'fields'->>'startsAt')
 or record->'fields'->>'kind'<>'lodging' and item.ends_at is not null and recovery_private.time_v1(record->'fields'->>'endsAt') is not null and item.ends_at>recovery_private.time_v1(record->'fields'->>'endsAt') then return jsonb_build_object('kind','pending','reason','RESERVATION_DATE_CONFLICT');end if;
 end if;
 end loop;
 snap:=public.trip_content_snapshot(t.id,t.title);if pg_column_size(snap)>262144 then return jsonb_build_object('kind','pending','reason','RECOVERY_SCOPE_TOO_LARGE');end if;
 if c.id is not null then
 if c.profile_basis<>profile or c.reservation_basis<>orders->'items' or c.snapshot<>snap or c.traffic_basis is distinct from p_traffic then return jsonb_build_object('kind','conflict');end if;return recovery_private.context_wire_v1(c);end if;
 insert into recovery_private.contexts_v1(owner_id,trip_id,operation_id,input,base_version,snapshot,profile_basis,reservation_basis,traffic_basis,digest,expires_at)
 values(u,t.id,(p_input->>'operationId')::uuid,p_input,t.head_version,snap,profile,orders->'items',p_traffic,recovery_private.hash_v1(jsonb_build_array(u,t.id,p_input,t.head_version,snap,profile,orders->'items')||case when p_traffic is null then '[]'::jsonb else jsonb_build_array(p_traffic) end),least(case when p_traffic is null then observed+interval '5 minutes' else recovery_private.time_v1(p_traffic->>'expiresAt') end,clock_timestamp()+interval '5 minutes')) returning * into c;
 return recovery_private.context_wire_v1(c);
exception when lock_not_available then return jsonb_build_object('kind','unavailable');end $function$

CREATE OR REPLACE FUNCTION recovery_private.profile_v1(u uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare p public.user_profiles%rowtype;begin
 select * into p from public.user_profiles where owner_id=u for share nowait;
 return jsonb_build_object('present',found,'travelPace',case when p.pace_state='explicit' and p.pace_notice='local-planning-cross-trip-v1' then p.travel_pace else null end,
 'updatedAt',recovery_private.ms_v1(p.updated_at),'timestamp',p.updated_at,'revision',p.pace_revision,'state',p.pace_state,'notice',p.pace_notice);
end $function$

CREATE OR REPLACE FUNCTION public.save_user_profile(p_display_name text, p_travel_pace text, p_locale text, p_currency text, p_distance_unit text, p_temperature_unit text, p_default_departure_time time without time zone)
 RETURNS TABLE(owner_id uuid, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
begin PERFORM identity_private.guard_mobile_rpc_v2();
  if (select auth.uid()) is null then raise exception 'FORBIDDEN'; end if;
  if nullif(trim(p_display_name), '') is not null and char_length(trim(p_display_name)) not between 1 and 80 then raise exception 'INVALID_PROFILE'; end if;
  if p_travel_pace not in ('relaxed', 'balanced', 'packed') or p_locale not in ('zh', 'en', 'es', 'ru', 'ar') or p_currency not in ('CNY', 'USD', 'EUR', 'RUB', 'SAR') or p_distance_unit not in ('kilometre', 'mile') or p_temperature_unit not in ('celsius', 'fahrenheit') then raise exception 'INVALID_PROFILE'; end if;
  insert into public.user_profiles(owner_id, display_name, travel_pace, locale, currency, distance_unit, temperature_unit, default_departure_time)
    values ((select auth.uid()), nullif(trim(p_display_name), ''), p_travel_pace, p_locale, p_currency, p_distance_unit, p_temperature_unit, p_default_departure_time)
  on conflict on constraint user_profiles_pkey do update set display_name = excluded.display_name, travel_pace = excluded.travel_pace, locale = excluded.locale, currency = excluded.currency, distance_unit = excluded.distance_unit, temperature_unit = excluded.temperature_unit, default_departure_time = excluded.default_departure_time, updated_at = now();
  return query select profile.owner_id, profile.updated_at from public.user_profiles profile where profile.owner_id = (select auth.uid());
end;
$function$

CREATE OR REPLACE FUNCTION scoped_edit_private.worker_policy_v1(u uuid, pid uuid, sid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare cfg scoped_edit_private.worker_settings_v1%rowtype;tp turn_private.text_policies%rowtype;pp turn_private.planning_policies%rowtype;begin
 select * into cfg from scoped_edit_private.worker_settings_v1 where policy_id=pid for share;
 select * into tp from turn_private.text_policies where id=pid for share;
 select * into pp from turn_private.planning_policies where id=cfg.planning_policy_id for share;
 if not exists(select 1 from turn_private.hosted_worker_control where singleton and enabled) or cfg.policy_id is null or not cfg.enabled or cfg.scope_id<>sid or cfg.expires_at<=clock_timestamp() or cfg.notice_hash is distinct from pp.notice_hash
 or pp.text_policy_id is distinct from tp.id or pp.revoked_at is not null or pp.effective_at>clock_timestamp() or pp.expires_at<=clock_timestamp()
 or not turn_private.text_policy_current(pid) or tp.provider<>'qwen' or tp.context_mode<>'current_input_v1'
 or not(tp.endpoint='https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions' or tp.endpoint ~ '^https://[a-z0-9][a-z0-9-]*[.]cn-beijing[.]maas[.]aliyuncs[.]com/compatible-mode/v1/chat/completions$')
 or not exists(select 1 from turn_private.text_consents where owner_id=u and policy_id=pid and revoked_at is null)
 or not exists(select 1 from turn_private.planning_consents where owner_id=u and policy_id=pp.id and revoked_at is null)
 or not exists(select 1 from public.model_budget_scopes where id=sid and owner_id=u and enabled and not frozen and expires_at>clock_timestamp())
 or not exists(select 1 from public.model_budget_provider_limits where scope_id=sid and provider='qwen' and model=cfg.model and price_version=cfg.price_version and enabled)
 then return false;end if;
 -- Explicit gate for source egress. Existing current-input consent alone is insufficient.
 if not cfg.allow_profile and exists(select 1 from public.user_profiles where owner_id=u and pace_state='explicit') then return false;end if;
 if not cfg.allow_memory and exists(select 1 from public.memory_profiles where owner_id=u and state in('explicit','confirmed') and summary is not null) then return false;end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION service_brief_private.affected(owner uuid, refs jsonb, tab text, row_data jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare i turn_private.assistant_travel_intakes;mid uuid:=nullif(refs->>'intakeMessageId','')::uuid;rid text:=row_data->>'id';
begin
 if tab='session' then return true;end if;
 if tab='user_profiles' then return coalesce((refs->>'profilePace')::boolean,false);end if;
 if tab='memory_profiles' and exists(select 1 from jsonb_array_elements(refs->'memories') x where x->>'id'=rid) then return true;end if;
 if tab='memory_receipts' and exists(select 1 from jsonb_array_elements(refs->'memories') x where x->>'id'=row_data->>'memory_id') then return true;end if;
 if tab='memory_consents' and exists(select 1 from jsonb_array_elements(refs->'memories') x join public.memory_profiles p on p.id=(x->>'id')::uuid where p.consent_id=rid::uuid) then return true;end if;
 if mid is null then return false;end if;
 select * into i from turn_private.assistant_travel_intakes where message_id=mid and owner_id=owner;
 if not found then return true;end if;
 if tab in('services','trips','trip_archives','trip_deletions') then return true;end if;
 if tab='text_policies' then return i.policy_id::text=rid;end if;
 if tab='text_consents' then return i.policy_id::text=row_data->>'policy_id' and i.owner_id::text=row_data->>'owner_id';end if;
 if tab='assistant_conversations' then return i.conversation_id::text=rid;end if;
 if tab in('assistant_messages','assistant_travel_intakes','assistant_goal_trip_links','assistant_goal_trip_receipts') then return i.goal_id::text=row_data->>'goal_id';end if;
 if tab='assistant_goals' then return i.goal_id::text=rid;end if;
 if tab='memory_profiles' then return exists(select 1 from jsonb_array_elements(i.memory_basis) x where x->>'id'=rid);end if;
 if tab='memory_receipts' then return exists(select 1 from jsonb_array_elements(i.memory_basis) x where x->>'id'=row_data->>'memory_id');end if;
 if tab='memory_consents' then return exists(select 1 from jsonb_array_elements(i.memory_basis) x join public.memory_profiles p on p.id=(x->>'id')::uuid where p.consent_id=rid::uuid);end if;
 return false;
end $function$

CREATE OR REPLACE FUNCTION service_brief_private.fields(c service_cases_private.cases, refs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare out jsonb;m jsonb;f jsonb;p jsonb;i jsonb;ints jsonb;k text;
begin
 out:=jsonb_build_array(jsonb_build_object('key','problem','field','problem','state','available','value',c.problem,'provenance','explicit',
 'source',jsonb_build_object('kind','case','id',c.id,'revision',c.revision,'updatedAt',service_operations_private.ms(coalesce((select max(created_at) from service_cases_private.audit where case_id=c.id and revision=c.revision),c.created_at)),
 'receiptId',null,'consentId',null,'basisDigest',service_brief_private.hash(to_jsonb(c)))));
 if (refs->>'profilePace')::boolean then p:=service_brief_private.profile_field(c.owner_id);end if;
 if refs->'intakeMessageId'<>'null'::jsonb then
 i:=service_brief_private.current_intake(c);
 if i->'source'->'id' is distinct from refs->'intakeMessageId' then i:=null;end if;
 end if;
 ints:=service_brief_private.intake_fields(i);
 foreach k in array array['travel_pace','budget','requirements'] loop
 select value into f from jsonb_array_elements(ints) where value->>'key'=k;
 if f is null and k='travel_pace' then f:=p;end if;
 out:=out||jsonb_build_array(coalesce(f,jsonb_build_object('key',k,'field',k,'state','unknown')));
 end loop;
 for m in select value from jsonb_array_elements(refs->'memories') order by value->>'id' loop
 f:=service_brief_private.memory_field(c.owner_id,(m->>'id')::uuid,(m->>'revision')::bigint);
 out:=out||jsonb_build_array(coalesce(f,jsonb_build_object('key','memory:'||(m->>'id'),'field','preference','state','unknown')));
 end loop;
 return out||jsonb_build_array(jsonb_build_object('key','response_detail','field','response_detail','state','unknown'));
end $function$

CREATE OR REPLACE FUNCTION service_brief_private.profile_field(owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p public.user_profiles;
begin
 select * into p from public.user_profiles where owner_id=owner for share nowait;
 if not found or p.pace_state<>'explicit' or p.pace_notice is distinct from 'local-planning-cross-trip-v1' or p.pace_operation is null or p.travel_pace not in('relaxed','balanced','packed') then return null;end if;
 return jsonb_build_object('key','travel_pace','field','travel_pace','state','available','value',p.travel_pace,'provenance','explicit',
 'source',jsonb_build_object('kind','profile_pace','id',owner,'revision',p.pace_revision,'updatedAt',service_operations_private.ms(p.updated_at),'receiptId',p.pace_operation,'consentId',null,'basisDigest',service_brief_private.hash(to_jsonb(p))));
end $function$

CREATE OR REPLACE FUNCTION service_brief_private.valid_sources(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare m jsonb; ids text[]:=array[]::text[];
begin
 if not service_operations_private.exact(v,array['profilePace','memories','intakeMessageId']) or jsonb_typeof(v->'profilePace') is distinct from 'boolean'
 or (v->'intakeMessageId'<>'null'::jsonb and not service_operations_private.uuid(v->'intakeMessageId')) or jsonb_typeof(v->'memories') is distinct from 'array' then return false;end if;
 if jsonb_array_length(v->'memories')>3 then return false;end if;
 for m in select value from jsonb_array_elements(v->'memories') loop
 if not service_operations_private.exact(m,array['id','revision']) or not service_operations_private.uuid(m->'id') or not service_operations_private.integer(m->'revision',1,9007199254740990) or m->>'id'=any(ids) then return false;end if;
 ids:=array_append(ids,m->>'id');end loop;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.service_case_brief_v1(p_input jsonb, p_request_bytes text, p_surface text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_variable
declare u uuid;sess uuid;a text;v jsonb;raw bytea;op uuid;cid uuid;dig text;abandon boolean:=false;business boolean;
 c service_cases_private.cases;b service_brief_private.briefs;p service_brief_private.previews;o service_brief_private.operations;
 f jsonb;out jsonb;chosen jsonb;refs jsonb;mems jsonb;profile jsonb;intake jsonb;m jsonb;events jsonb;rev bigint;ts timestamptz;expiry timestamptz;n integer;
begin
 u:=service_brief_private.actor();sess:=(auth.jwt()->>'session_id')::uuid;
 if p_surface is null or p_surface not in('owner','staff') or p_request_bytes is null or octet_length(convert_to(p_request_bytes,'UTF8')) not between 2 and 48000 then raise exception 'INVALID_INPUT';end if;
 begin v:=p_request_bytes::jsonb;exception when others then raise exception 'INVALID_INPUT';end;
 if v is distinct from p_input then raise exception 'INVALID_INPUT';end if;
 a:=v->>'action';raw:=convert_to(p_request_bytes,'UTF8');
 if a='abandon' then
 if not service_operations_private.exact(v,array['action','operationId','mutationBytes']) or not service_operations_private.uuid(v->'operationId') or jsonb_typeof(v->'mutationBytes') is distinct from 'string' then raise exception 'INVALID_INPUT';end if;
 begin v:=(p_input->>'mutationBytes')::jsonb;exception when others then raise exception 'INVALID_INPUT';end;
 if v->'operationId' is distinct from p_input->'operationId' or coalesce(v->>'action','') not in('share','withdraw','delete') then raise exception 'INVALID_INPUT';end if;
 raw:=convert_to(p_input->>'mutationBytes','UTF8');abandon:=true;
 end if;
 if octet_length(raw)>24000 or service_brief_private.valid(v) is distinct from true then raise exception 'INVALID_INPUT';end if;
 if p_surface='staff' and a not in('read','locate') then raise exception 'CASE_FORBIDDEN';end if;
 business:=a in('source_options','preview','share','read_preview','locate','read');
 if business and not exists(select 1 from service_brief_private.settings where enabled) then raise exception 'BRIEF_DISABLED';end if;
 if a='export' then return service_brief_private.export(u,sess,(v->>'requestId')::uuid);end if;
 if v ? 'operationId' then
 op:=(v->>'operationId')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('traveler-brief:'||u||':'||sess||':'||p_surface||':'||op,0));
 select * into o from service_brief_private.operations where actor_id=u and session_id=sess and surface=p_surface and operation_id=op;
 if o.erased then raise exception 'BRIEF_OPERATION_ERASED';end if;
 end if;
 if a='read_operation' then
 if o.operation_id is null then return jsonb_build_object('receipt',null);end if;
 -- Content-free deletion recovery needs only the original authenticated session.
 if o.receipt->>'action'='delete' and o.receipt->>'outcome'='applied' then return jsonb_build_object('receipt',o.receipt);end if;
 cid:=o.case_id;
 elsif a='read_preview' then
 select * into p from service_brief_private.previews where id=(v->>'previewId')::uuid and owner_id=u and session_id=sess;
 if not found then raise exception 'BRIEF_NOT_FOUND';end if;cid:=p.case_id;
 else cid:=(v->>'caseId')::uuid;
 end if;
 -- Case -> Brief -> source NOWAIT. Source writers use the reverse order and
 -- their BEFORE triggers use Case NOWAIT, so neither side can form a deadlock.
 select * into c from service_cases_private.cases where id=cid for update nowait;
 if not found then
 if o.receipt->>'action'='delete' and o.receipt->>'outcome'='applied' then
 dig:=encode(pg_catalog.sha256(raw),'hex');if dig<>o.request_digest then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;return o.receipt;
 end if;raise exception 'CASE_FORBIDDEN';end if;
 perform service_brief_private.qualify(c,u,p_surface,business);
 select * into b from service_brief_private.briefs where case_id=cid for update nowait;
 rev:=coalesce(b.revision,0);
 if op is not null then
 select * into o from service_brief_private.operations where actor_id=u and session_id=sess and surface=p_surface and operation_id=op for update;
 if o.erased then raise exception 'BRIEF_OPERATION_ERASED';end if;
 end if;
 if a='read_operation' or o.operation_id is not null then
 if a<>'read_operation' then
 dig:=encode(pg_catalog.sha256(raw),'hex');if o.request_digest<>dig then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;
 end if;
 if o.receipt->>'action'='delete' and o.receipt->>'outcome'='applied' then
 if a='read_operation' then return jsonb_build_object('receipt',o.receipt);else return o.receipt;end if;
 end if;
 if c.recipient_id::text is distinct from convert_from(o.request_bytes,'UTF8')::jsonb->>'recipientId' or c.revision<>(o.receipt->>'grantRevision')::integer then raise exception 'BRIEF_FORBIDDEN';end if;
 if o.receipt->>'action'='share' and o.receipt->>'outcome'='applied' then
 perform service_brief_private.qualify(c,u,'owner',true);
 if b.revision<>(o.receipt->>'revision')::bigint then raise exception 'BRIEF_STALE';end if;
 perform service_brief_private.current_fields(c,b);
 end if;
 if a='read_operation' then return jsonb_build_object('receipt',o.receipt);else return o.receipt;end if;
 end if;
 if a='owner_state' then
 return jsonb_build_object('schemaVersion','traveler-brief/1','kind','owner_state','caseId',cid,'ownerId',u,'recipientId',c.recipient_id,'grantRevision',c.revision,'briefRevision',rev,'state',coalesce(b.state,'absent'));
 end if;
 if a='audit' then
 select count(*) into n from service_brief_private.audit where case_id=cid;if n>200 then raise exception 'BRIEF_LIMIT';end if;
 select coalesce(jsonb_agg(service_brief_private.audit_json(e) order by e.created_at,e.event_id),'[]') into events from service_brief_private.audit e where e.case_id=cid;
 return jsonb_build_object('schemaVersion','traveler-brief/1','kind','audit','caseId',cid,'ownerId',u,'revision',rev,'events',events,'complete',true);
 end if;
 if a='source_options' then
 profile:=service_brief_private.profile_field(u);mems:=service_brief_private.memory_options(u);intake:=service_brief_private.current_intake(c);
 if intake is not null then intake:=jsonb_build_object('messageId',intake->'source'->'id','revision',intake->'source'->'revision','updatedAt',intake->'source'->'updatedAt','fields',service_brief_private.intake_fields(intake));end if;
 if c.expires_at<=clock_timestamp() then raise exception 'BRIEF_FORBIDDEN';end if;
 return jsonb_build_object('schemaVersion','traveler-brief/1','kind','source_options','caseId',cid,'ownerId',u,'recipientId',c.recipient_id,'grantRevision',c.revision,'expiresAt',service_operations_private.ms(c.expires_at),'profilePace',profile,'memories',mems,'memoryScope','latest_three_preferences','intake',intake);
 end if;
 if a='locate' then
 perform service_brief_private.current_fields(c,b);
 if p_surface='staff' then perform service_brief_private.event(c,rev,u,'read',b.selected_keys);end if;
 return service_brief_private.binding(c)||jsonb_build_object('kind','locator','revision',rev,'expiresAt',service_operations_private.ms(b.expires_at));
 end if;
 if a='read_preview' then
 select * into p from service_brief_private.previews where id=(v->>'previewId')::uuid and owner_id=u and session_id=sess for update nowait;
 if not found or p.expires_at<=clock_timestamp() or p.grant_revision<>c.revision or p.recipient_id<>c.recipient_id or p.revision<>rev then raise exception 'BRIEF_STALE';end if;
 f:=service_brief_private.fields(c,p.sources);dig:=service_brief_private.hash(service_brief_private.binding(c)||jsonb_build_object('fields',f));
 if dig<>p.source_digest then raise exception 'BRIEF_STALE';end if;
 return service_brief_private.binding(c)||jsonb_build_object('kind','preview','previewId',p.id,'revision',p.revision,'sourceDigest',dig,'createdAt',service_operations_private.ms(p.created_at),'expiresAt',service_operations_private.ms(p.expires_at),'fields',f,'noticeVersion','case-minimal-brief/1');
 end if;
 if c.recipient_id::text is distinct from v->>'recipientId' or c.revision::text is distinct from v->>'grantRevision' then raise exception 'BRIEF_CONFLICT';end if;
 if a='preview' then
 refs:=v->'sources';mems:=service_brief_private.memory_options(u);
 for m in select value from jsonb_array_elements(refs->'memories') loop
 if not exists(select 1 from jsonb_array_elements(mems) candidate where candidate->'source'->'id'=m->'id' and candidate->'source'->'revision'=m->'revision') then raise exception 'BRIEF_STALE';end if;
 end loop;
 if refs->'intakeMessageId'<>'null'::jsonb and service_brief_private.current_intake(c)->'source'->'id' is distinct from refs->'intakeMessageId' then raise exception 'BRIEF_STALE';end if;
 f:=service_brief_private.fields(c,refs);dig:=service_brief_private.hash(service_brief_private.binding(c)||jsonb_build_object('fields',f));
 ts:=clock_timestamp();expiry:=least(c.expires_at,ts+interval '5 minutes');if expiry<=ts then raise exception 'BRIEF_FORBIDDEN';end if;
 select count(*) into n from service_brief_private.previews where owner_id=u;if n>=200 then raise exception 'BRIEF_LIMIT';end if;
 insert into service_brief_private.previews(case_id,owner_id,session_id,revision,recipient_id,grant_revision,sources,source_digest,created_at,expires_at)
 values(cid,u,sess,rev,c.recipient_id,c.revision,refs,dig,ts,expiry) returning * into p;
 perform service_brief_private.event(c,rev,u,'previewed','[]');
 return service_brief_private.binding(c)||jsonb_build_object('kind','preview','previewId',p.id,'revision',rev,'sourceDigest',dig,'createdAt',service_operations_private.ms(p.created_at),'expiresAt',service_operations_private.ms(p.expires_at),'fields',f,'noticeVersion','case-minimal-brief/1');
 end if;
 if rev<>(v->>'expectedRevision')::bigint then raise exception 'BRIEF_CONFLICT';end if;
 if a='read' then
 f:=service_brief_private.current_fields(c,b);
 if p_surface='staff' then perform service_brief_private.event(c,rev,u,'read',b.selected_keys);end if;
 return service_brief_private.binding(c)||jsonb_build_object('kind','brief','revision',rev,'updatedAt',service_operations_private.ms(b.updated_at),'expiresAt',service_operations_private.ms(b.expires_at),'sourceDigest',b.source_digest,'fields',f,'noticeVersion','case-minimal-brief/1');
 end if;
 dig:=encode(pg_catalog.sha256(raw),'hex');ts:=clock_timestamp();
 if not abandon then
 if rev>=9007199254740990 then raise exception 'BRIEF_LIMIT';end if;
 if a='share' then
 select * into p from service_brief_private.previews where id=(v->>'previewId')::uuid and owner_id=u and session_id=sess and case_id=cid for update nowait;
 if not found or p.expires_at<=ts or p.recipient_id<>c.recipient_id or p.grant_revision<>c.revision or p.revision<>rev or p.source_digest<>v->>'sourceDigest' then raise exception 'BRIEF_STALE';end if;
 f:=service_brief_private.fields(c,p.sources);
 if service_brief_private.hash(service_brief_private.binding(c)||jsonb_build_object('fields',f))<>p.source_digest then raise exception 'BRIEF_STALE';end if;
 chosen:=service_brief_private.selected(f,v->'selectedKeys');
 if jsonb_array_length(chosen)<>jsonb_array_length(v->'selectedKeys') or exists(select 1 from jsonb_array_elements(chosen) where value->>'state'<>'available') then raise exception 'BRIEF_FORBIDDEN';end if;
 refs:=service_brief_private.selected_refs(chosen);
 perform service_brief_private.erase(cid,u);
 insert into service_brief_private.briefs(case_id,owner_id,revision,recipient_id,grant_revision,state,selected_keys,sources,source_digest,updated_at,expires_at)
 values(cid,u,rev+1,c.recipient_id,c.revision,'shared',v->'selectedKeys',refs,service_brief_private.hash(service_brief_private.binding(c)||jsonb_build_object('fields',chosen)),ts,c.expires_at)
 on conflict(case_id) do update set revision=excluded.revision,recipient_id=excluded.recipient_id,grant_revision=excluded.grant_revision,state=excluded.state,selected_keys=excluded.selected_keys,sources=excluded.sources,source_digest=excluded.source_digest,updated_at=excluded.updated_at,expires_at=excluded.expires_at;
 perform service_brief_private.event(c,rev+1,u,'shared',v->'selectedKeys');
 elsif v->>'action' in('withdraw','delete') then
 perform service_brief_private.erase(cid,u,v->>'action'='delete');
 insert into service_brief_private.briefs(case_id,owner_id,revision,recipient_id,grant_revision,state,updated_at)
 values(cid,u,rev+1,c.recipient_id,c.revision,case when v->>'action'='delete' then 'deleted' else 'withdrawn' end,ts)
 on conflict(case_id) do update set revision=excluded.revision,recipient_id=excluded.recipient_id,grant_revision=excluded.grant_revision,state=excluded.state,selected_keys='[]',sources=null,source_digest=null,updated_at=excluded.updated_at,expires_at=null;
 if v->>'action'='withdraw' then perform service_brief_private.event(c,rev+1,u,'withdrawn','[]');end if;
 else raise exception 'INVALID_INPUT';end if;
 rev:=rev+1;
 end if;
 out:=jsonb_build_object('schemaVersion','traveler-brief/1','kind','receipt','operationId',op,'requestDigest',dig,'action',v->>'action','outcome',case when abandon then 'cancelled' else 'applied' end,'caseId',cid,'revision',rev,'grantRevision',c.revision,'createdAt',service_operations_private.ms(ts));
 insert into service_brief_private.operations(actor_id,session_id,surface,operation_id,case_id,request_digest,request_bytes,receipt,created_at) values(u,sess,p_surface,op,cid,dig,raw,out,ts);
 return out;
exception when lock_not_available then raise exception 'BRIEF_BUSY';
end $function$

CREATE OR REPLACE FUNCTION public.submit_local_recovery_v1(p_trip_id uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$declare u uuid;t public.trips%rowtype;c recovery_private.contexts_v1%rowtype;o recovery_private.operations_v1%rowtype;profile jsonb;orders jsonb;patch jsonb;p uuid;rev integer;base integer;expiry timestamptz;receipt jsonb;dig text;traffic jsonb;begin
 if p_trip_id is null or not recovery_private.valid_select_v1(p_input) then raise exception 'INVALID_INPUT';end if;
 u:=recovery_private.actor_v1();t:=recovery_private.trip_v1(u,p_trip_id);if t.id is null then return jsonb_build_object('kind','unavailable');end if;
 select * into o from recovery_private.operations_v1 where owner_id=u and operation_id=(p_input->>'operationId')::uuid;
 if found then if o.trip_id<>t.id or o.input<>p_input then return jsonb_build_object('kind','conflict');end if;return o.receipt||'{"reused":true}';end if;
 select * into c from recovery_private.contexts_v1 where id=(p_input->>'contextId')::uuid and owner_id=u and trip_id=t.id for update nowait;
 if not found then return jsonb_build_object('kind','unavailable');end if;
 if c.digest is distinct from p_input->>'contextDigest' or exists(select 1 from recovery_private.operations_v1 where context_id=c.id) or p_input->>'candidateId'='omit_selected' and jsonb_array_length(c.input->'selectedItemIds')<2 then return jsonb_build_object('kind','conflict');end if;
 if c.expires_at<=clock_timestamp() then return jsonb_build_object('kind','stale');end if;
 if t.head_version<>c.base_version or public.trip_content_snapshot(t.id,t.title)<>c.snapshot then return jsonb_build_object('kind','conflict');end if;
 profile:=recovery_private.profile_v1(u);orders:=recovery_private.reservations_v1(u,t.id,t.head_version);if orders->>'kind' is distinct from 'basis' then return orders;end if;
 if profile<>c.profile_basis or orders->'items'<>c.reservation_basis then return jsonb_build_object('kind','conflict');end if;
 if c.traffic_basis is not null then
 traffic:=recovery_private.transport_basis_v1((c.traffic_basis->>'receiptId')::uuid,c.traffic_basis->'scope');
 if traffic is distinct from c.traffic_basis then return jsonb_build_object('kind','pending','reason','TRANSPORT_RECEIPT_UNAVAILABLE');end if;
